#!/usr/bin/env bash
#
# and record — record the screen of one device and pull the mp4 into ~/Downloads.
#
# AI DISCLOSURE: This script was entirely generated by an AI tool
set -uo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib/common.sh"
source "$AND_LIB/device.sh"

usage() {
  cat <<USAGE
and record

Starts \`screenrecord\` on the device and keeps recording until you press
enter (or ctrl-c). The video is then pulled to ~/Downloads as
"<device> - <timestamp>.mp4" and removed from the device.

Android caps a single recording at 3 minutes; if that is hit first the video
is saved as-is.
USAGE
}

case "${1:-}" in
  -h|--help|help) usage; exit 0 ;;
  "") ;;
  *) log "and record: takes no arguments"; usage >&2; exit 1 ;;
esac

resolve_device
banner "RECORD" "and record" "$DEVICE_LABEL"

name="${DEVICE_LABEL%% (*}"
timestamp="$(date +"%Y-%m-%d at %H.%M.%S")"
remote="/sdcard/and-record-$$.mp4"
target="$HOME/Downloads/$name - $timestamp.mp4"

"${ADB[@]}" shell screenrecord "$remote" &
rec_pid=$!

# screenrecord only finalises the mp4 on SIGINT, and killing the local adb
# client would not reach it, so signal the process on the device instead.
stop_recording() {
  "${ADB[@]}" shell 'kill -2 $(pidof screenrecord)' >/dev/null 2>&1
  wait "$rec_pid" 2>/dev/null
}
trap 'stop_recording; "${ADB[@]}" shell rm -f "$remote" >/dev/null 2>&1; exit 130' INT TERM

sleep 1
if ! kill -0 "$rec_pid" 2>/dev/null; then
  die "screenrecord failed to start on $DEVICE_LABEL"
fi

printf ' %s%s●%s Recording… %sPress enter to stop%s\n' "$BOLD" "$RED" "$RESET" "$BOLD" "$RESET"
# Poll so the loop also ends when screenrecord stops by itself (time limit).
while kill -0 "$rec_pid" 2>/dev/null; do
  read -r -t 1 && break
done
stop_recording

# The device needs a moment to write the mp4 trailer after SIGINT.
sleep 1
if "${ADB[@]}" pull "$remote" "$target" >/dev/null 2>&1; then
  ok "$name → $target"
  "${ADB[@]}" shell rm -f "$remote" >/dev/null 2>&1
else
  "${ADB[@]}" shell rm -f "$remote" >/dev/null 2>&1
  die "failed to pull the recording from $DEVICE_LABEL"
fi
